export type MessageKey = keyof typeof messages;
export const locales = Object.freeze(["en", "es", "fr", "de", "ja", "zh-CN"] as const);
export type Locale = typeof locales[number];
export type LanguageChoice = Locale | "auto";
export type PreferenceIssue = "invalid" | "unavailable" | "unsaved";
export const languageStorageKey = "codealta.desktop.language.v1";
export const languageNames: Readonly<Record<Locale, string>> = Object.freeze({ en: "English", es: "Español", fr: "Français", de: "Deutsch", ja: "日本語", "zh-CN": "中文（简体）" });
export const validLanguage = (value: unknown): value is LanguageChoice => value === "auto" || locales.some(locale => locale === value);
export function resolveLocale(choice: string, browserLanguages: readonly string[] = []): Locale {
  if (choice !== "auto") return locales.find(locale => locale === choice) ?? "en";
  for (const tag of browserLanguages.slice(0, 8)) {
    if (typeof tag !== "string" || tag.length > 35 || !/^[a-z]{2}(?:-[a-z0-9]{2,8})*$/i.test(tag)) continue;
    const base = tag.split("-")[0].toLowerCase();
    if (base === "zh") return "zh-CN";
    const locale = locales.find(value => value === base); if (locale) return locale;
  }
  return "en";
}
export function translate(locale: string, key: MessageKey, parameters: Readonly<Record<string, string | number>> = {}): string {
  const index = locales.findIndex(value => value === locale);
  const template = index <= 0 ? key : messages[key][index - 1];
  return template.replace(/\{(\w+)\}/g, (match, name: string) => Object.hasOwn(parameters, name) ? String(parameters[name]) : match);
}
export function readLanguage(read: () => string | null): { choice: LanguageChoice; issue?: PreferenceIssue } {
  try { const value = read(); return value === null ? { choice: "auto" } : validLanguage(value) ? { choice: value } : { choice: "en", issue: "invalid" }; }
  catch { return { choice: "en", issue: "unavailable" }; }
}
export function saveLanguage(value: string, write: (value: string) => void): { choice: LanguageChoice; issue?: PreferenceIssue } | null {
  if (!validLanguage(value)) return null;
  try { write(value); return { choice: value }; } catch { return { choice: value, issue: "unsaved" }; }
}
export function preferenceNotice(locale: Locale, label: MessageKey, fallback: string, issue?: PreferenceIssue) {
  if (!issue) return "";
  return translate(locale, issue === "invalid" ? "{label}: invalid saved preference; using {fallback}. Not overwritten."
    : issue === "unavailable" ? "{label}: local storage unavailable; using {fallback}. Not saved."
    : "{label}: applied in this window, but local storage could not save the change.", { label: translate(locale, label), fallback });
}
